<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {request} from './api'
type Link={id:string;objective_submission_id:string;subjective_submission_id:string;active:number;reason:string;confirmed_at:string}
type Paper={id?:string;submission_id?:string;anonymous_code?:string;state:string;page_count:number;score:number|null;max_score:number|null}
type Listing={links:Link[];objective_submissions:Paper[];subjective_submissions:Paper[]}
const props=defineProps<{assignmentId:string;selectedExamId?:string}>()
const exams=ref<{exam_id:string;assignment_id:string;title:string}[]>([]),exam=ref(''),data=ref<Listing>(),objective=ref(''),subjective=ref(''),editing=ref(''),busy=ref(false),error=ref(''),message=ref(''),historyPage=ref(1)
let revision=0
const obj=computed(()=>data.value?.objective_submissions.find(p=>p.submission_id===objective.value)),sub=computed(()=>data.value?.subjective_submissions.find(p=>p.id===subjective.value))
const historyPages=computed(()=>Math.max(1,Math.ceil((data.value?.links.length||0)/25)))
const historyRows=computed(()=>data.value?.links.slice((historyPage.value-1)*25,historyPage.value*25)||[])
function used(id:string,kind:'objective_submission_id'|'subjective_submission_id'){return data.value?.links.some(l=>l.active&&l.id!==editing.value&&l[kind]===id)}
function reset(){objective.value='';subjective.value='';editing.value=''}
const score=(p:Paper)=>p.score===null?'尚无有效确认成绩':`${p.score} / ${p.max_score}`
async function load(){const n=++revision;busy.value=true;error.value='';reset();try{const d=await request<Listing>('/objective/api/answer-links?exam_id='+exam.value);if(n===revision)data.value=d}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(l:Link){reset();editing.value=l.id;objective.value=l.objective_submission_id;subjective.value=l.subjective_submission_id}
async function write(action:string,id?:string){if(busy.value)return;busy.value=true;error.value='';try{await request('/objective/api/answer-links','POST',{exam_id:exam.value,action,link_id:id||editing.value||undefined,objective_submission_id:objective.value,subjective_submission_id:subjective.value,confirmed:true,originals_checked:true});await load();message.value=action==='unlink'?'已解除关联，两侧原成绩保留。':'关联已保存，整卷成绩将按有效评分自动汇总。'}catch(e){error.value=(e as Error).message+'；请刷新核实，不会自动重试。'}finally{busy.value=false}}
onMounted(async()=>{try{exams.value=(await request<{exams:typeof exams.value}>('/objective/api/source-exams')).exams.filter(e=>e.assignment_id===props.assignmentId);exam.value=props.selectedExamId||exams.value[0]?.exam_id||'';if(!exams.value.some(e=>e.exam_id===exam.value))throw new Error('考试不存在或不可访问');await load()}catch(e){error.value=(e as Error).message}})
</script>
<template><section aria-label="答卷关联"><h3>合并两类答卷（可选）</h3><p>整卷一次上传会自动关联。分开上传时，选择同一考生的两份原卷后点击确认；不按顺序或文件名猜测。不关联也可查看、分析和导出单侧成绩。</p>
<label v-if="!selectedExamId">考试<select v-model="exam" @change="load"><option v-for="e in exams" :key="e.exam_id" :value="e.exam_id">{{e.title}}</option></select></label><button :disabled="busy||!exam" @click="load">刷新关联</button><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<fieldset v-if="data" :disabled="busy" class="answer-link-form"><legend>{{editing?'更正关联':'选择对应答卷'}}</legend><div class="link-pickers"><section><label>客观题答卷<select aria-label="客观题答卷" v-model="objective"><option value="">请选择</option><option v-for="p in data.objective_submissions" :key="p.submission_id" :value="p.submission_id" :disabled="used(p.submission_id!,'objective_submission_id')">{{p.anonymous_code||p.submission_id?.slice(0,8)}} · {{score(p)}}</option></select></label><template v-if="obj"><p>答卷 {{obj.submission_id?.slice(0,8)}} · {{score(obj)}} · {{obj.page_count}}页</p><a v-if="obj.page_count" :href="'/objective/api/submissions/'+objective+'/pages/1'" target="_blank" rel="noopener"><img class="link-thumbnail" :src="'/objective/api/submissions/'+objective+'/pages/1'" alt="所选客观题原卷缩略图"></a><details v-if="obj.page_count>1"><summary>其余原卷页</summary><a v-for="i in obj.page_count-1" :key="i" :href="'/objective/api/submissions/'+objective+'/pages/'+(i+1)" target="_blank" rel="noopener">第{{i+1}}页 </a></details></template></section>
<section><label>主观题答卷<select aria-label="主观题答卷" v-model="subjective"><option value="">请选择</option><option v-for="p in data.subjective_submissions" :key="p.id" :value="p.id" :disabled="used(p.id!,'subjective_submission_id')">{{p.id?.slice(0,8)}} · {{score(p)}}</option></select></label><template v-if="sub"><p>答卷 {{sub.id?.slice(0,8)}} · {{score(sub)}} · {{sub.page_count}}页</p><a v-if="sub.page_count" :href="'/api/submission-photo?submission_id='+subjective+'&photo_index=1'" target="_blank" rel="noopener"><img class="link-thumbnail" :src="'/api/submission-photo?submission_id='+subjective+'&photo_index=1'" alt="所选主观题原卷缩略图"></a><details v-if="sub.page_count>1"><summary>其余原卷页</summary><a v-for="i in sub.page_count-1" :key="i" :href="'/api/submission-photo?submission_id='+subjective+'&photo_index='+(i+1)" target="_blank" rel="noopener">第{{i+1}}页 </a></details></template></section></div>
<button class="primary" :disabled="!objective||!subjective" @click="write(editing?'replace':'link')">{{editing?'确认更正关联':'确认这两份属于同一考生并关联'}}</button><button v-if="editing" @click="reset">取消更正</button></fieldset>
<details v-if="data"><summary>已有关联与解除记录（{{data.links.length}}条）</summary><div class="context-actions"><button :disabled="historyPage<=1" @click="historyPage--">上一页</button><span>{{historyPage}} / {{historyPages}}</span><button :disabled="historyPage>=historyPages" @click="historyPage++">下一页</button></div><article v-for="l in historyRows" :key="l.id"><p>{{l.objective_submission_id.slice(0,8)}} ↔ {{l.subjective_submission_id.slice(0,8)}} · {{l.active?'已关联':'已解除'}}</p><button v-if="l.active" :disabled="busy" @click="edit(l)">更正</button><button v-if="l.active" :disabled="busy" @click="write('unlink',l.id)">解除关联</button><details><summary>操作记录</summary><p>{{l.confirmed_at}} · {{l.reason}}</p></details></article></details></section></template>
<style scoped>.link-pickers{display:grid;grid-template-columns:1fr 1fr;gap:20px}.link-pickers section{min-width:0}.link-thumbnail{display:block;width:100%;height:260px;object-fit:contain;background:#f5f7fa;margin:12px 0}button{margin:8px 8px 8px 0}@media(max-width:600px){.link-pickers{grid-template-columns:1fr}.link-thumbnail{height:200px}}</style>
